var e=[{title:`Базове положення в бігу`,text:`Біжіть випрямленим і розслабленим, з легким природним нахилом уперед усім тілом і вільним помахом рук. Тримайте плечі розслабленими і не виносьте ногу далеко вперед із кожним кроком. Ваш крок має відчуватися узгодженим на обраній швидкості, без примусу в жорсткий шаблон.`},{title:`Каденс і постановка стопи`,text:`Каденс: це кількість кроків за хвилину. Деяким бігунам може бути корисно трохи його змінити, але немає правила, що всі мають бігти з 180 кроками за хвилину. Постановка на п’яту, середину стопи чи передню частину стопи розподіляє сили по-різному, і дані не підтверджують, що кожен здоровий бігун має перейти на один тип приземлення.`},{title:`Інтервали ходьби й бігу`,text:`Як початківець, ви можете чергувати одну хвилину легкого бігу з двома хвилинами ходьби протягом 15–20 хвилин, плюс розминка та заминка. Протягом кількох тижнів подовжуйте частини бігу. Нарощуйте за часом, впевненістю та тим, наскільки важко відчувається, і робіть перерви на ходьбу, коли захочете. Правильний стартовий обсяг залежить від того, наскільки активними ви були, як ваше тіло з цим справляється та від покриття, тож немає фіксованого розкладу, якого всі мають дотримуватися.`},{title:`Спринти: окрема навичка`,text:`Швидкі прискорення значно більше навантажують м’язи та сухожилля. Розвиньте базову бігову форму, перш ніж спринтувати на повній швидкості, і розминайтеся довше, коли додаєте швидші зусилля. Зупиніться, якщо відчуваєте різкий біль або біль, що посилюється. Обирайте взуття та маршрут, що відповідають покриттю й умовам, а якщо біг суперечить вашим обмеженням на удари або у вас немає безпечного маршруту, робіть кондиційні вправи з низьким ударним навантаженням.`}];var i=[{label:`Систематичний огляд: техніка постановки стопи та ризик травм`,url:`https://pubmed.ncbi.nlm.nih.gov/34527750/`},{label:`Систематичний огляд каденсу бігу та ризику травм`,url:`https://pubmed.ncbi.nlm.nih.gov/40964543/`},{label:`CDC: рекомендації щодо фізичної активності для дорослих`,url:`https://www.cdc.gov/physical-activity-basics/guidelines/adults.html`}];var s={sections:e,sources:i};export{s as default,e as sections,i as sources};